package cn.paletale.companion;
import com.google.gson.*;
import java.util.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import static cn.paletale.companion.MarketTheme.*;
/** Private favorites with the same sidebar layout as the other archive pages. */
final class FavoritesHub extends WindowScreen {
 private static String adActor;private static java.net.URI adSite;private static final LinkedHashMap<String,MarketData.Page> AD_CACHE=new LinkedHashMap<>();
 static void clearAdCache(){AD_CACHE.clear();adActor=null;adSite=null;}
 private static void scopeAds(String actor,java.net.URI site){if(!Objects.equals(adActor,actor)||!Objects.equals(adSite,site)){clearAdCache();adActor=actor;adSite=site;}}
 private final Screen parent;private final MarketApi api;private final java.util.function.Supplier<String> tokens;private final WorldApi world=new WorldApi();private boolean players=true,loading,started;private String token,error="";private int page=1,total,size,generation;private List<JsonObject> rows=List.of();private MarketData.Page ads;
 FavoritesHub(Screen parent,MarketApi api){this(parent,api,PaleTaleClient.ACCOUNT::token);}
 FavoritesHub(Screen parent,MarketApi api,java.util.function.Supplier<String> tokens){super(Component.literal("我的收藏"));this.parent=parent;this.api=api;this.tokens=tokens;}
 /** The ad cards are laid out like the plaza's grid: {columns, card width, card height, cards per screen}. */
 private int[] adGrid(ArchiveLayout l){int area=height-108,columns=Math.max(2,Math.min(6,l.contentWidth()/92)),cw=(l.contentWidth()-(columns-1)*6)/columns,cover=Math.round((cw-2)*10f/16),smallest=Math.round(cover*.5f)+60,gridRows=Math.max(1,Math.min(Math.max(1,MarketPaging.MAX_ROWS/columns),(area+6)/(smallest+6))),ch=Math.min(cover+64,(area-(gridRows-1)*6)/gridRows);return new int[]{columns,cw,ch,columns*gridRows};}
 /** Clicking the place on a card starts the navigation, as in the plaza. */
 @Override public boolean mouseClicked(net.minecraft.client.input.MouseButtonEvent event,boolean twice){if(event.button()==0){double mx=(event.x()-winX)/windowScale,my=(event.y()-winY)/windowScale;for(var child:children())if(child instanceof MarketCardButton card&&card.onPlace(mx,my)){var t=card.place();Navigation.start(new Navigation.Target(t.name(),t.x(),t.y(),t.z(),t.kind(),t.marks()));return true;}}return super.mouseClicked(event,twice);}
 @Override protected void init(){fitWindow();var l=ArchiveLayout.of(width);String actor=tokens.get();if(!Objects.equals(token,actor)){token=actor;rows=List.of();ads=null;started=false;generation++;}ArchiveNavigation.tabs(this::addRenderableWidget,parent,api,ArchiveNavigation.Tab.FAVORITES,l.left(),l.panelWidth());addRenderableWidget(new Action(PaleTaleClient.ACCOUNT.label(),l.left()+l.panelWidth()-(l.panelWidth()<600?88:96),13,l.panelWidth()<600?88:96,18,false,"person",b->PaleTaleClient.ACCOUNT.checkStatus(minecraft)));
  addRenderableWidget(new Action("收藏玩家",l.left(),62,l.sidebar(),18,players,null,b->{players=true;page=1;started=false;rows=List.of();ads=null;load();}));addRenderableWidget(new Action("收藏广告",l.left(),84,l.sidebar(),18,!players,null,b->{players=false;page=1;started=false;rows=List.of();ads=null;load();}));addRenderableWidget(new Action("刷新",l.left(),height-34,l.sidebar(),18,false,null,b->{WorldEntityScreen.clearFavoriteCache();clearAdCache();load();}));
  int cols=Math.max(2,l.contentWidth()/84),gridRows=Math.max(1,Math.min(4,(height-110)/44));int targetSize=Math.min(48,cols*gridRows);if(players&&size!=targetSize&&started){size=targetSize;page=1;started=false;}size=targetSize;
  if(players){int cw=(l.contentWidth()-(cols-1)*6)/cols,ch=Math.max(40,Math.min(94,(height-110-(gridRows-1)*6)/gridRows));for(int i=0;i<rows.size();i++){var row=rows.get(i);String name=WorldShopTable.value(row,"name");var card=new ArchiveCardButton(WorldPortrait.favorite(row),api,l.contentX()+i%cols*(cw+6),65+i/cols*(ch+6),cw,ch,b->{if(row.has("eligible")&&row.get("eligible").getAsBoolean()&&row.get("current").getAsBoolean())minecraft.setScreen(new WorldEntityScreen(this,api,"player",name));else if(row.has("playerId")&&!row.get("playerId").isJsonNull())minecraft.setScreen(new ArchiveDetailScreen(this,api,ArchiveData.Kind.PLAYERS,row.get("playerId").getAsInt()));});card.showOnline=true;card.active=!loading&&(row.has("eligible")&&row.get("eligible").getAsBoolean()&&row.get("current").getAsBoolean()||row.has("playerId")&&!row.get("playerId").isJsonNull());addRenderableWidget(card);}}
  else if(ads!=null){int[] grid=adGrid(l);for(int i=0;i<Math.min(grid[3],ads.ads().size());i++){var ad=ads.ads().get(i);var card=addRenderableWidget(new MarketCardButton(ad,api,l.contentX()+i%grid[0]*(grid[1]+6),70+i/grid[0]*(grid[2]+6),grid[1],grid[2],b->minecraft.setScreen(new MarketDetailScreen(this,MarketScreen.favorites(this,api),api,ad))));var place=card.place();card.setTips(null,place==null?null:net.minecraft.client.gui.components.Tooltip.create(Component.literal("导航到广告主设置的地址\n"+place.x()+", "+place.z()+(place.y()==null?"":", "+place.y()))));}}
  addRenderableWidget(new Action("上一页",l.contentX(),height-31,60,18,false,null,b->{page--;load();})).active=!loading&&page>1;addRenderableWidget(new Action("下一页",l.left()+l.panelWidth()-60,height-31,60,18,false,null,b->{page++;load();})).active=!loading&&(players?page*size<total:ads!=null&&ads.hasMore());if(!started&&token!=null)load();if(token==null)error="请先登录后查看收藏。";
 }
 private void load(){if(token==null){rebuildWidgets();return;}started=true;loading=true;error="";int run=++generation;String actor=token;boolean selected=players;int requested=page;var site=api.site();String diskOwner=DiskPages.owner(site),diskKey=(selected?"players:":"ads:")+requested+":"+(selected?size:adGrid(ArchiveLayout.of(width))[3]);boolean[] fresh={false};(selected?DiskPages.read(diskOwner,diskKey,JsonObject.class):DiskPages.read(diskOwner,diskKey,MarketData.Page.class)).thenAccept(snapshot->minecraft.execute(()->{if(snapshot==null||fresh[0]||run!=generation||minecraft.screen!=this||!Objects.equals(actor,tokens.get()))return;try{if(selected){var value=(JsonObject)snapshot;var out=new ArrayList<JsonObject>();for(var item:value.getAsJsonArray("players"))out.add(item.getAsJsonObject());if(out.size()>size)return;rows=List.copyOf(out);total=value.get("total").getAsInt();}else ads=(MarketData.Page)snapshot;loading=false;rebuildWidgets();}catch(RuntimeException ignored){}}));if(selected){var cached=WorldEntityScreen.cachedFavoritePage(actor,site,requested,size);if(cached!=null){var out=new ArrayList<JsonObject>();for(var item:cached.getAsJsonArray("players"))out.add(item.getAsJsonObject());rows=List.copyOf(out);total=cached.get("total").getAsInt();loading=false;}}if(selected)world.call(site,"/api/mcmod/world/favorites?view=all&page="+requested+"&size="+size,actor,null).whenComplete((v,e)->minecraft.execute(()->{if(run!=generation||!Objects.equals(actor,tokens.get())||minecraft.screen!=this)return;fresh[0]=e==null;loading=false;if(e!=null){error=WorldApi.problem(e);if(error.startsWith("登录已过期")){fresh[0]=true;rows=List.of();total=0;DiskPages.clear(diskOwner);WorldEntityScreen.clearFavoriteCache();}}else try{var out=new ArrayList<JsonObject>();for(var item:v.getAsJsonArray("players")){var row=item.getAsJsonObject();if(!WorldShopTable.value(row,"uuid").matches("[a-f0-9]{32}"))throw new IllegalArgumentException();out.add(row);}rows=List.copyOf(out);total=v.get("total").getAsInt();page=v.get("page").getAsInt();WorldEntityScreen.rememberFavoritePage(actor,site,page,size,v);DiskPages.write(diskOwner,diskKey,v);}catch(RuntimeException invalid){error="收藏数据暂不可用。";}rebuildWidgets();}));else {int visible=adGrid(ArchiveLayout.of(width))[3],batch=MarketPaging.firstBatch(requested,visible);scopeAds(actor,site);String cacheKey=requested+":"+visible;var cached=AD_CACHE.get(cacheKey);if(cached!=null){ads=cached;loading=false;}api.favorites(actor,batch).thenCompose(first->MarketPaging.needsNext(requested,visible,first)?api.favorites(actor,batch+1).thenApply(second->MarketPaging.window(requested,visible,first,second)):java.util.concurrent.CompletableFuture.completedFuture(MarketPaging.window(requested,visible,first,null))).whenComplete((v,e)->minecraft.execute(()->{if(run!=generation||!Objects.equals(actor,tokens.get())||minecraft.screen!=this)return;fresh[0]=e==null;loading=false;if(e!=null){error="收藏广告暂时无法读取，请稍后重试。";Throwable cause=e;while(cause.getCause()!=null)cause=cause.getCause();if(cause.getMessage()!=null&&cause.getMessage().contains("HTTP 401")){fresh[0]=true;ads=null;DiskPages.clear(diskOwner);clearAdCache();}}else{boolean unchanged=Objects.equals(ads,v);ads=v;DiskPages.write(diskOwner,diskKey,v);AD_CACHE.put(cacheKey,v);while(AD_CACHE.size()>32)AD_CACHE.remove(AD_CACHE.keySet().iterator().next());if(unchanged&&cached!=null&&error.isEmpty())return;}rebuildWidgets();}));}rebuildWidgets();}
 @Override protected void renderWindow(GuiGraphics g,int x,int y,float d){var l=ArchiveLayout.of(width);l.draw(g,height);ArchiveNavigation.brand(g,l.left(),l.panelWidth());super.renderWindow(g,x,y,d);text(g,"★ 我的收藏",l.left()+4,47,l.sidebar()-8,INK);text(g,players?"收藏玩家（"+total+"）":"收藏广告"+(ads==null?"":"（"+ads.total()+"）"),l.contentX()+2,48,l.contentWidth()-4,INK);if(!error.isEmpty())text(g,error,l.contentX(),height-46,l.contentWidth(),MarketTheme.c(0xFFAF4545));else if(loading)text(g,"正在读取收藏…",l.contentX(),height-46,l.contentWidth(),MUTED);}
 @Override public void tick(){super.tick();if(!Objects.equals(token,tokens.get()))rebuildWidgets();}
 @Override public void removed(){generation++;loading=false;started=false;}
 @Override public void onClose(){minecraft.setScreen(parent);}
}
